parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": ["plumbing", "electrical", "hvac", "appliance", "general"],
      "description": "The type of maintenance issue described by the tenant"
    },
    "urgency": {
      "type": "string",
      "enum": ["emergency", "high", "medium", "low"],
      "description": "How urgently this issue needs to be addressed. Use 'emergency' only for issues posing an immediate safety or property risk (active flooding, no heat in freezing weather, exposed live wiring, gas smell, etc.)."
    }
  },
  "required": ["category", "urgency"]
}

parameters.text:
=Tenant: {{ $json.fields.tenant_name }}
Unit Number:{{ $json.fields.unit_number }}
Category:{{ $json.fields.category }}
Description:{{ $json.fields.description }}
Urgency:{{ $json.fields.urgency }}
Contact Number:{{ $json.fields.contact_phone }}
Created at:{{ $json.fields.created_at }}

